import 'package:flutter/material.dart';import 'package:provider/provider.dart';import '../../providers/task_store.dart';import '../../widgets/task_tile.dart';import 'task_editor.dart';
class TasksScreen extends StatefulWidget{const TasksScreen({super.key});@override State<TasksScreen> createState()=>_TasksScreenState();}
class _TasksScreenState extends State<TasksScreen>{String filter='all';@override Widget build(BuildContext context){final s=context.watch<TaskStore>();final list=s.filtered.where((t)=>filter=='all'||(filter=='open'&&!t.completed)||(filter=='done'&&t.completed)||(filter=='today'&&s.today.any((x)=>x.id==t.id))||(filter=='overdue'&&s.overdue.any((x)=>x.id==t.id))).toList();return Scaffold(appBar:AppBar(title:const Text('مهامي',style:TextStyle(fontWeight:FontWeight.bold)),actions:[PopupMenuButton<String>(onSelected:(v)=>setState(()=>s.sort=v),itemBuilder:(_)=>const [PopupMenuItem(value:'date',child:Text('الترتيب حسب الموعد')),PopupMenuItem(value:'priority',child:Text('حسب الأولوية')),PopupMenuItem(value:'created',child:Text('الأحدث أولًا'))])]),body:Column(children:[Padding(padding:const EdgeInsets.fromLTRB(16,4,16,8),child:TextField(decoration:const InputDecoration(hintText:'ابحث في المهام...',prefixIcon:Icon(Icons.search)),onChanged:(v)=>s.search=v)),SizedBox(height:48,child:ListView(scrollDirection:Axis.horizontal,padding:const EdgeInsets.symmetric(horizontal:12),children:[_chip('all','الكل'),_chip('open','غير مكتملة'),_chip('done','مكتملة'),_chip('today','اليوم'),_chip('overdue','متأخرة')])),Expanded(child:s.loading?const Center(child:CircularProgressIndicator()):list.isEmpty?_empty(context):ListView.builder(padding:const EdgeInsets.fromLTRB(12,8,12,100),itemCount:list.length,itemBuilder:(ctx,i){final t=list[i];return TaskTile(key:ValueKey(t.id),task:t,onToggle:()=>s.toggle(t),onEdit:()=>showTaskEditor(context,task:t),onDelete:()=>_delete(context,t,s));}))]));}
 Widget _chip(String v,String label)=>Padding(padding:const EdgeInsets.symmetric(horizontal:4),child:ChoiceChip(label:Text(label),selected:filter==v,onSelected:(_)=>setState(()=>filter=v)));
 Widget _empty(BuildContext c)=>Center(child:Padding(padding:const EdgeInsets.all(32),child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.task_alt_rounded,size:70,color:Theme.of(c).colorScheme.primary.withOpacity(.65)),const SizedBox(height:12),Text('لا توجد مهام هنا',style:Theme.of(c).textTheme.titleLarge),const SizedBox(height:5),const Text('أضف مهمة جديدة وابدأ بتنظيم يومك.')] )));
 Future<void> _delete(BuildContext c,t,s)async{final ok=await showDialog<bool>(context:c,builder:(d)=>AlertDialog(title:const Text('حذف المهمة؟'),content:Text('سيتم حذف «${t.title}». يمكنك التراجع بعد الحذف.'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('حذف'))]));if(ok==true){await s.remove(t);if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(SnackBar(content:const Text('تم حذف المهمة'),action:SnackBarAction(label:'تراجع',onPressed:()async{await s.save(t);})));}}
}
